const $=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg';
const types={AC:[['MCB','เบรกเกอร์ 2P','2P • AC',80,2],['RCCB','เครื่องตัดไฟรั่ว','2P • AC',100,2],['SPD','ป้องกันไฟกระชาก','AC',80,2],['N BAR','บาร์นิวทรัล','N',110,4],['PE BAR','บาร์สายดิน','PE',110,4]],DC:[['DC MCB','เบรกเกอร์ DC','2P • DC',80,2],['FUSE','ฟิวส์สตริง','DC',60,1],['DC SPD','ป้องกันไฟกระชาก','DC',80,2],['ISOLATOR','สวิตช์ตัดตอน','2P • DC',100,2],['PE BAR','บาร์สายดิน','PE',110,4]]};
let data={AC:{devices:[],wires:[]},DC:{devices:[],wires:[]}},mode='AC',tool='move',selected=null,start=null,drag=null,history=[];
try{const saved=JSON.parse(localStorage.getItem('panel-studio-v1'));if(saved&&valid(saved))data=saved}catch{}
function valid(d){return ['AC','DC'].every(m=>d[m]&&Array.isArray(d[m].devices)&&d[m].devices.length<=100&&Array.isArray(d[m].wires)&&d[m].wires.length<=400&&d[m].devices.every(x=>typeof x.id==='string'&&types[m].some(t=>t[0]===x.type)&&typeof x.label==='string'&&typeof x.rating==='string'&&Number.isFinite(x.x)&&Number.isFinite(x.y)&&x.x>=0&&x.x<=800&&x.y>=0&&x.y<=560)&&d[m].wires.every(w=>typeof w.id==='string'&&/^#[0-9a-f]{6}$/i.test(w.color)&&[w.a,w.b].every(e=>e&&typeof e.id==='string'&&Number.isInteger(e.i)&&e.i>=0&&e.i<8&&d[m].devices.some(x=>x.id===e.id))))}
function state(){return data[mode]}function checkpoint(){history.push(JSON.stringify(data));if(history.length>60)history.shift()}function persist(){try{localStorage.setItem('panel-studio-v1',JSON.stringify(data))}catch{$('status').textContent='พื้นที่บันทึกเต็ม กรุณาบันทึกเป็น JSON'}}
function el(tag,attrs={},text){let e=document.createElementNS(NS,tag);for(let k in attrs)e.setAttribute(k,attrs[k]);if(text!==undefined)e.textContent=text;return e}
function spec(d){return types[mode].find(t=>t[0]===d.type)}function ports(d){let t=spec(d),n=t[4];return Array.from({length:n*2},(_,i)=>({x:d.x+(i%n+1)*t[3]/(n+1),y:d.y+(i<n?0:100),label:d.type.includes('BAR')?d.type.split(' ')[0]:mode==='AC'?(i%n===0?'L':'N'):(n===1?'+':i%n===0?'+':'−')}))}
function point(e){let p=$('board').createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform($('board').getScreenCTM().inverse())}function endpoint(e){let d=state().devices.find(d=>d.id===e.id);return d&&ports(d)[e.i]}
function render(){let b=$('board');b.replaceChildren();let defs=el('defs'),pat=el('pattern',{id:'grid',width:20,height:20,patternUnits:'userSpaceOnUse'});pat.append(el('circle',{cx:1,cy:1,r:1,fill:'#d8e1e6'}));defs.append(pat);b.append(defs,el('rect',{width:800,height:560,fill:'url(#grid)'}));[80,240,400].forEach((y,i)=>{b.append(el('text',{x:22,y:y-20,fill:'#91a1aa','font-size':11},'DIN 0'+(i+1)),el('rect',{x:25,y:y+35,width:750,height:30,class:'rail',rx:2}),el('line',{x1:25,x2:775,y1:y+44,y2:y+44,stroke:'#faffff'}))});
state().wires.forEach(w=>{let a=endpoint(w.a),c=endpoint(w.b);if(!a||!c)return;let offset=a.y===c.y?a.y-27:(a.y+c.y)/2;let path=el('path',{d:`M${a.x},${a.y} V${offset} H${c.x} V${c.y}`,fill:'none',stroke:w.color,'stroke-width':4,'stroke-linejoin':'round',class:'wire'});path.addEventListener('click',()=>{checkpoint();state().wires=state().wires.filter(x=>x.id!==w.id);render();persist()});b.append(path)});
state().devices.forEach(d=>{let t=spec(d),g=el('g',{class:'device'});g.append(el('rect',{x:d.x,y:d.y,width:t[3],height:100,rx:5,fill:'#fff',stroke:selected===d.id?'#087f70':'#9dadb7','stroke-width':selected===d.id?3:1.5}),el('rect',{x:d.x+9,y:d.y+32,width:t[3]-18,height:25,rx:3,fill:d.type.includes('BAR')?'#b8a05d':'#273d49'}),el('text',{x:d.x+t[3]/2,y:d.y+25,'text-anchor':'middle','font-size':10,fill:'#1e3846'},d.label.slice(0,16)),el('text',{x:d.x+t[3]/2,y:d.y+76,'text-anchor':'middle','font-size':9,fill:'#74858f'},d.rating.slice(0,18)));
g.addEventListener('pointerdown',e=>{if(tool!=='move')return;selected=d.id;let p=point(e);checkpoint();drag={id:d.id,dx:p.x-d.x,dy:p.y-d.y};b.setPointerCapture(e.pointerId);render();properties()});
ports(d).forEach((p,i)=>{g.append(el('text',{x:p.x,y:p.y+(i<t[4]?14:-8),'text-anchor':'middle','font-size':8,fill:'#71828c'},p.label));let c=el('circle',{cx:p.x,cy:p.y,r:6,fill:start?.id===d.id&&start.i===i?'#f0aa31':'#e1e8eb',stroke:'#607883','stroke-width':2,class:'terminal'});c.addEventListener('pointerdown',e=>{e.stopPropagation();if(tool!=='wire'){selected=d.id;render();properties();return}connect({id:d.id,i})});g.append(c)});b.append(g)});
$('count').textContent=state().devices.length;$('wcount').textContent=state().wires.length;let counts={};state().devices.forEach(d=>counts[d.type]=(counts[d.type]||0)+1);$('bom').textContent=Object.entries(counts).map(([k,v])=>`${k} × ${v}`).join(' · ')}
function properties(){let d=state().devices.find(d=>d.id===selected);$('props').hidden=!d;$('empty').hidden=!!d;if(d){$('label').value=d.label;$('rating').value=d.rating}}
function connect(p){if(!start){start=p;$('status').textContent='เลือกขั้วปลายทาง';render();return}if(start.id===p.id){$('status').textContent='เลือกขั้วของอุปกรณ์อีกตัว';return}checkpoint();state().wires.push({id:crypto.randomUUID(),a:start,b:p,color:$('color').value});start=null;render();persist();$('status').textContent='เชื่อมสายแล้ว • เลือกขั้วเพื่อเริ่มสายใหม่'}
function add(type,x=70,y=80){let t=types[mode].find(t=>t[0]===type);if(!t)return;checkpoint();let d={id:crypto.randomUUID(),type,label:type,rating:'ระบุพิกัด',x:Math.max(25,Math.min(775-t[3],Math.round(x/10)*10)),y:[80,240,400].reduce((a,b)=>Math.abs(b-y)<Math.abs(a-y)?b:a)};state().devices.push(d);selected=d.id;render();properties();persist();$('status').textContent='เพิ่มอุปกรณ์แล้ว ลากเพื่อจัดตำแหน่ง'}
function setMode(m){mode=m;selected=start=null;['AC','DC'].forEach(x=>$(x.toLowerCase()).classList.toggle('active',x===m));$('title').textContent=m==='AC'?'ตู้ Consumer Unit':'ตู้ Solar Combiner';$('catalog').replaceChildren();types[m].forEach(t=>{let b=document.createElement('button');b.className='part';b.draggable=true;b.innerHTML=`<span class="icon">▥</span><span>${t[0]}<small>${t[1]}</small></span>`;b.onclick=()=>add(t[0],60+(state().devices.length%6)*110,80+Math.floor(state().devices.length/6)%3*160);b.ondragstart=e=>e.dataTransfer.setData('text/plain',t[0]);$('catalog').append(b)});$('color').replaceChildren();let colors=m==='AC'?[['#8b543c','L · น้ำตาล'],['#2878c8','N · น้ำเงิน'],['#47934a','PE · เขียว']]:[['#dd5353','+ · แดง'],['#303b47','− · ดำ'],['#47934a','PE · เขียว']];colors.forEach(([v,n])=>$('color').add(new Option(n,v)));$('legend').textContent=colors.map(x=>x[1]).join('     /     ');render();properties()}
$('board').onpointermove=e=>{if(!drag)return;let d=state().devices.find(x=>x.id===drag.id),p=point(e);d.x=Math.max(25,Math.min(775-spec(d)[3],Math.round((p.x-drag.dx)/10)*10));d.y=Math.max(35,Math.min(425,p.y-drag.dy));render()};function endDrag(){if(!drag)return;let d=state().devices.find(x=>x.id===drag.id);d.y=[80,240,400].reduce((a,b)=>Math.abs(b-d.y)<Math.abs(a-d.y)?b:a);drag=null;render();persist()}$('board').onpointerup=endDrag;$('board').onpointercancel=endDrag;$('board').ondragover=e=>e.preventDefault();$('board').ondrop=e=>{e.preventDefault();let p=point(e);add(e.dataTransfer.getData('text/plain'),p.x-40,p.y-50)};
['move','wire'].forEach(t=>$(t).onclick=()=>{tool=t;start=null;['move','wire'].forEach(x=>$(x).classList.toggle('active',x===t));$('status').textContent=t==='wire'?'คลิกขั้วต้นทางและปลายทางเพื่อวาดสาย':'ลากอุปกรณ์เพื่อจัดวาง';render()});$('ac').onclick=()=>setMode('AC');$('dc').onclick=()=>setMode('DC');
['label','rating'].forEach(k=>$(k).onchange=()=>{let d=state().devices.find(x=>x.id===selected);if(d){checkpoint();d[k]=$(k).value;render();persist()}});
function remove(){if(!selected)return;checkpoint();state().devices=state().devices.filter(d=>d.id!==selected);state().wires=state().wires.filter(w=>w.a.id!==selected&&w.b.id!==selected);selected=start=null;render();properties();persist()}$('remove').onclick=remove;document.onkeydown=e=>{if(e.key==='Delete'&&!['INPUT','SELECT'].includes(document.activeElement.tagName))remove();if(e.key==='Escape'){start=null;render()}};$('undo').onclick=()=>{if(history.length){data=JSON.parse(history.pop());selected=start=null;render();properties();persist()}};$('clear').onclick=()=>{if(confirm('ล้างอุปกรณ์และสายในโหมด '+mode+'?')){checkpoint();data[mode]={devices:[],wires:[]};selected=start=null;render();properties();persist()}};
function download(name,content,type){let u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}$('save').onclick=()=>download('panel-studio.json',JSON.stringify(data,null,2),'application/json');$('export').onclick=()=>{let s=$('board').cloneNode(true);s.setAttribute('xmlns',NS);s.setAttribute('width','800');s.setAttribute('height','560');s.querySelectorAll('.rail').forEach(r=>{r.setAttribute('fill','#d7dfe4');r.setAttribute('stroke','#b3bfc7')});download('panel-'+mode+'.svg',new XMLSerializer().serializeToString(s),'image/svg+xml')};$('open').onclick=()=>$('file').click();$('file').onchange=async()=>{try{let f=$('file').files[0];if(!f)return;if(f.size>1000000)throw Error();let d=JSON.parse(await f.text());if(!valid(d))throw Error();checkpoint();data=d;selected=start=null;render();properties();persist();$('status').textContent='เปิดแบบเรียบร้อย'}catch{$('status').textContent='ไฟล์ไม่ถูกต้อง กรุณาเลือก JSON ที่บันทึกจาก Panel Studio'}$('file').value=''};setMode('AC');
